import { timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Two conventions used by every table, so no table drifts:
 *   - primary keys are uuid v4, generated by the database
 *   - timestamps are `timestamptz`, never naive — the salon is in Asia/Kolkata
 *     but the servers are not.
 *
 * Business dates are a separate `date` column on the rows that need reporting.
 * See docs/DATA_MODEL.md for why.
 */

export const id = () => uuid('id').primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp('created_at', { withTimezone: true, mode: 'date' }).defaultNow().notNull();

export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' })
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date());

/** Nullable timestamptz for "this has not happened yet" moments. */
export const nullableTs = (name: string) =>
  timestamp(name, { withTimezone: true, mode: 'date' });
